package org.millenaire.common.item;import net.minecraft.world.item.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;public record InvItem(Item item,int meta){public Item getItem(){return item;}public static InvItem createInvItem(Item i,int m){return new InvItem(i,m);}public static InvItem createInvItem(Item i){return new InvItem(i,0);}public static InvItem createInvItem(Block b){return new InvItem(b.asItem(),0);}public static InvItem createInvItem(Block b,int m){return new InvItem(b.asItem(),m);}public static InvItem createInvItem(BlockState s){return new InvItem(s.getBlock().asItem(),0);}}